mapper.update:
UPDATE new_prdct
	SET dscnt=1
	WHERE sale_id=#{saleId} and prdct_id =#{prdctId}

UPDATE new_prdct
	SET dscnt_prcnt=#{dscntPrcnt}
		,earn_prcnt=#{earnPrcnt}
		,using_point=#{usingPoint}
	WHERE
		sale_id=#{saleId}
		and prdct_id =#{prdctId}

UPDATE salePrdct_off
	SET dscnt_prcnt=#{dscntPrcnt}
	,earn_prcnt=#{earnPrcnt}
	,using_point=#{usingPoint}
	WHERE
		sale_id=#{saleId}
		and prdct_id =#{prdctId}
		and itemTy=#{itemTy}
